-- KostCycle: ALL migrations in order, for a NEW, EMPTY Supabase project.
-- Generated by `npm run build:sql`. Do not edit by hand.
-- Paste into Supabase > SQL Editor > New query and press Run ONCE.
-- Never run this on a project that already has the KostCycle tables.
-- Contains: 202609210001_kostcycle_multiuser.sql, 202610120001_feedback_admin_demo.sql, 202610260001_binus_student_email.sql, 202611210001_reservations_chat_images.sql

-- ===========================================================================
-- 202609210001_kostcycle_multiuser.sql
-- ===========================================================================
-- Run this entire migration in the Supabase SQL Editor, once, as the project owner.
-- No frontend secret keys are required. Existing auth users are backfilled below.
begin;

create schema if not exists kostcycle_private;
revoke all on schema kostcycle_private from public, anon, authenticated;

create function public.kostcycle_category_weight(category text)
returns numeric language sql immutable set search_path = '' as $$
  select case category when 'Fans' then 2.5 when 'Lamps' then 1.0
    when 'Storage' then 1.2 when 'Furniture' then 5.0 when 'Kitchen' then 1.0
    when 'Electronics' then 1.5 else 1.0 end;
$$;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  university text not null default 'BINUS University' check (char_length(university) between 1 and 120),
  campus text not null default 'Alam Sutera' check (char_length(campus) between 1 and 120),
  residence text not null default 'Newton Kost' check (char_length(residence) between 1 and 120),
  verified boolean not null default true,
  verification_type text not null default 'simulated' check (verification_type = 'simulated'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on column public.profiles.verified is 'Simulated MVP status only. Not university identity verification.';

create table public.listings (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.profiles(id) on delete restrict,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  category text not null check (category in ('Fans','Lamps','Storage','Furniture','Kitchen','Electronics','Other Essentials')),
  condition text not null check (condition in ('Like New','Good','Fair')),
  price bigint not null check (price between 0 and 100000000),
  is_free boolean generated always as (price = 0) stored,
  university text not null default 'BINUS University' check (char_length(university) between 1 and 120),
  campus text not null default 'Alam Sutera' check (char_length(campus) between 1 and 120),
  residence text not null check (residence in ('Newton Kost','Silkwood Residence','Rukita Alam Sutera','The Prominence','Other')),
  distance integer not null default 150 check (distance between 0 and 100000),
  pickup text[] not null check (cardinality(pickup) between 1 and 3 and pickup <@ array['Today','Tomorrow','This weekend']::text[] and array_position(pickup,null) is null),
  description text not null check (char_length(btrim(description)) between 1 and 1500),
  image_index integer not null default 0 check (image_index between 0 and 11),
  image_data text check (image_data is null or (octet_length(image_data) <= 1700000 and image_data ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$')),
  status text not null default 'AVAILABLE' check (status in ('AVAILABLE','RESERVED','COMPLETED')),
  estimated_weight numeric generated always as (public.kostcycle_category_weight(category)) stored,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on column public.listings.distance is 'Static residence-based estimate, not GPS or a measured user-relative distance.';
comment on column public.listings.estimated_weight is 'Category estimate in kilograms; not measured environmental impact.';

create table public.reservations (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null unique references public.listings(id) on delete restrict,
  buyer_id uuid not null references public.profiles(id) on delete restrict,
  seller_id uuid not null references public.profiles(id) on delete restrict,
  pickup_location text not null,
  pickup_period text not null check (pickup_period in ('Today','Tomorrow','This weekend')),
  pickup_date date not null,
  status text not null default 'RESERVED' check (status in ('RESERVED','COMPLETED')),
  estimated_weight numeric not null check (estimated_weight > 0),
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  check (buyer_id <> seller_id),
  check ((status = 'RESERVED' and completed_at is null) or (status = 'COMPLETED' and completed_at is not null))
);
comment on table public.reservations is 'One transaction per listing; completion and impact are derived from this single record.';

-- Not exposed by the Data API or included in the realtime publication.
create table kostcycle_private.pickup_secrets (
  reservation_id uuid primary key references public.reservations(id) on delete cascade,
  code text not null check (code ~ '^[0-9]{4}$'),
  failed_attempts integer not null default 0,
  locked_until timestamptz
);
alter table kostcycle_private.pickup_secrets enable row level security;
revoke all on kostcycle_private.pickup_secrets from public, anon, authenticated;

create table public.saved_items (
  user_id uuid not null references public.profiles(id) on delete cascade,
  listing_id uuid not null references public.listings(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key(user_id, listing_id)
);

create index listings_seller_idx on public.listings(seller_id);
create index listings_browse_idx on public.listings(status, distance);
create index listings_created_idx on public.listings(created_at desc);
create index reservations_buyer_idx on public.reservations(buyer_id, created_at desc);
create index reservations_seller_idx on public.reservations(seller_id, created_at desc);
create index saved_items_listing_idx on public.saved_items(listing_id);

create function kostcycle_private.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end;
$$;
create trigger profiles_updated before update on public.profiles for each row execute function kostcycle_private.touch_updated_at();
create trigger listings_updated before update on public.listings for each row execute function kostcycle_private.touch_updated_at();
create trigger reservations_updated before update on public.reservations for each row execute function kostcycle_private.touch_updated_at();

create function kostcycle_private.create_student_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles(id,name,university,campus,residence)
  values (new.id,
    left(coalesce(nullif(btrim(new.raw_user_meta_data->>'name'),''),'Student'),80),
    left(coalesce(nullif(btrim(new.raw_user_meta_data->>'university'),''),'BINUS University'),120),
    left(coalesce(nullif(btrim(new.raw_user_meta_data->>'campus'),''),'Alam Sutera'),120),
    left(coalesce(nullif(btrim(new.raw_user_meta_data->>'residence'),''),'Newton Kost'),120));
  return new;
end;
$$;
create trigger kostcycle_auth_user_created after insert on auth.users
for each row execute function kostcycle_private.create_student_profile();

-- Backfill accounts created before this migration; email addresses are never copied.
insert into public.profiles(id,name,university,campus,residence)
select id,
  left(coalesce(nullif(btrim(raw_user_meta_data->>'name'),''),'Student'),80),
  left(coalesce(nullif(btrim(raw_user_meta_data->>'university'),''),'BINUS University'),120),
  left(coalesce(nullif(btrim(raw_user_meta_data->>'campus'),''),'Alam Sutera'),120),
  left(coalesce(nullif(btrim(raw_user_meta_data->>'residence'),''),'Newton Kost'),120)
from auth.users on conflict(id) do nothing;

alter table public.profiles enable row level security;
alter table public.listings enable row level security;
alter table public.reservations enable row level security;
alter table public.saved_items enable row level security;

-- Public profile fields are intentionally limited to marketplace identity, no email.
create policy profiles_read on public.profiles for select to anon, authenticated using (true);
create policy profiles_update_self on public.profiles for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy listings_read on public.listings for select to anon, authenticated using (true);
create policy listings_insert_self on public.listings for insert to authenticated
  with check ((select auth.uid()) = seller_id and status = 'AVAILABLE');
create policy listings_update_self_available on public.listings for update to authenticated
  using ((select auth.uid()) = seller_id and status = 'AVAILABLE')
  with check ((select auth.uid()) = seller_id and status = 'AVAILABLE');
create policy listings_delete_self_available on public.listings for delete to authenticated
  using ((select auth.uid()) = seller_id and status = 'AVAILABLE');
create policy reservations_participants_read on public.reservations for select to authenticated
  using ((select auth.uid()) = buyer_id or (select auth.uid()) = seller_id);
create policy saved_items_read_self on public.saved_items for select to authenticated using ((select auth.uid()) = user_id);
create policy saved_items_insert_self on public.saved_items for insert to authenticated with check ((select auth.uid()) = user_id);
create policy saved_items_delete_self on public.saved_items for delete to authenticated using ((select auth.uid()) = user_id);

-- RLS is complemented by column privileges. No client can set lifecycle or identity fields.
revoke all on public.profiles, public.listings, public.reservations, public.saved_items from public, anon, authenticated;
grant select on public.profiles, public.listings to anon, authenticated;
grant update(name,university,campus,residence) on public.profiles to authenticated;
grant insert(seller_id,name,category,condition,price,university,campus,residence,distance,pickup,description,image_index,image_data) on public.listings to authenticated;
grant update(name,category,condition,price,residence,distance,pickup,description,image_index,image_data) on public.listings to authenticated;
grant delete on public.listings to authenticated;
grant select on public.reservations to authenticated;
grant select,delete on public.saved_items to authenticated;
grant insert(user_id,listing_id) on public.saved_items to authenticated;

create function public.reserve_item(p_listing_id uuid, p_pickup_period text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_user uuid := auth.uid();
  v_listing public.listings%rowtype;
  v_id uuid;
  v_code text;
  v_today date := (now() at time zone 'Asia/Jakarta')::date;
  v_pickup_date date;
begin
  if v_user is null then raise exception 'Sign in to reserve an item.'; end if;
  if not exists(select 1 from public.profiles where id = v_user) then raise exception 'Your student profile is not ready.'; end if;
  -- Lock serializes competing buyers; the losing request sees RESERVED after waiting.
  select * into v_listing from public.listings where id = p_listing_id for update;
  if not found or v_listing.status <> 'AVAILABLE' then raise exception 'This item is no longer available to reserve.'; end if;
  if v_listing.seller_id = v_user then raise exception 'You cannot reserve your own listing.'; end if;
  if p_pickup_period is null or not (p_pickup_period = any(v_listing.pickup)) then raise exception 'Choose an available pickup period.'; end if;
  v_pickup_date := case p_pickup_period when 'Today' then v_today when 'Tomorrow' then v_today + 1
    else v_today + case when extract(isodow from v_today)::int >= 6 then 0 else 6 - extract(isodow from v_today)::int end end;
  insert into public.reservations(listing_id,buyer_id,seller_id,pickup_location,pickup_period,pickup_date,estimated_weight)
    values(v_listing.id,v_user,v_listing.seller_id,
      case when v_listing.residence = 'Other' then 'Residence common area' else v_listing.residence || ' lobby' end,
      p_pickup_period,v_pickup_date,v_listing.estimated_weight) returning id into v_id;
  -- Cryptographically random UUID entropy, reduced to a four-digit presentation code.
  v_code := (1000 + (('x' || substr(replace(gen_random_uuid()::text,'-',''),1,4))::bit(16)::int % 9000))::text;
  insert into kostcycle_private.pickup_secrets(reservation_id,code) values(v_id,v_code);
  update public.listings set status = 'RESERVED' where id = v_listing.id;
  return v_id;
end;
$$;

create function public.my_pickup_codes()
returns table(listing_id uuid, code text) language sql security definer stable set search_path = '' as $$
  select r.listing_id,s.code from public.reservations r
  join kostcycle_private.pickup_secrets s on s.reservation_id = r.id
  where r.buyer_id = (select auth.uid()) and r.status = 'RESERVED';
$$;

create function public.confirm_handoff(p_listing_id uuid, p_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_user uuid := auth.uid();
  v_listing public.listings%rowtype;
  v_reservation public.reservations%rowtype;
  v_secret kostcycle_private.pickup_secrets%rowtype;
begin
  if v_user is null then raise exception 'Sign in to confirm a handoff.'; end if;
  select * into v_listing from public.listings where id = p_listing_id for update;
  if not found or v_listing.seller_id <> v_user then raise exception 'Only this listing''s seller can confirm the handoff.'; end if;
  if v_listing.status <> 'RESERVED' then raise exception 'This handoff is no longer awaiting confirmation.'; end if;
  select * into v_reservation from public.reservations where listing_id = p_listing_id and status = 'RESERVED' for update;
  if not found then raise exception 'No active reservation exists.'; end if;
  select * into v_secret from kostcycle_private.pickup_secrets where reservation_id = v_reservation.id for update;
  if not found then raise exception 'Pickup verification is unavailable. Contact the project administrator.'; end if;
  if v_secret.locked_until > now() then
    return jsonb_build_object('ok',false,'message','Too many attempts. Wait 15 minutes after the last failed attempt, then try again.');
  end if;
  if v_secret.locked_until is not null then
    update kostcycle_private.pickup_secrets set failed_attempts = 0, locked_until = null where reservation_id = v_reservation.id;
    v_secret.failed_attempts := 0;
  end if;
  if p_code is null or p_code !~ '^[0-9]{4}$' or p_code <> v_secret.code then
    -- Return, rather than raise, so failed-attempt accounting commits.
    update kostcycle_private.pickup_secrets set failed_attempts = v_secret.failed_attempts + 1,
      locked_until = case when v_secret.failed_attempts >= 4 then now() + interval '15 minutes' else null end
    where reservation_id = v_reservation.id;
    return jsonb_build_object('ok',false,'message',case when v_secret.failed_attempts >= 4 then 'Too many attempts. Try again in 15 minutes.' else 'Code does not match this reservation.' end);
  end if;
  update public.reservations set status = 'COMPLETED', completed_at = now() where id = v_reservation.id;
  update public.listings set status = 'COMPLETED' where id = v_listing.id;
  delete from kostcycle_private.pickup_secrets where reservation_id = v_reservation.id;
  return jsonb_build_object('ok',true);
end;
$$;

revoke all on function public.reserve_item(uuid,text), public.confirm_handoff(uuid,text), public.my_pickup_codes() from public, anon, authenticated;
grant execute on function public.reserve_item(uuid,text), public.confirm_handoff(uuid,text), public.my_pickup_codes() to authenticated;
revoke all on function kostcycle_private.create_student_profile(), kostcycle_private.touch_updated_at() from public, anon, authenticated;
revoke all on function public.kostcycle_category_weight(text) from public;
grant execute on function public.kostcycle_category_weight(text) to anon, authenticated;

-- No codes or secrets are ever published. RLS filters reservation events to participants.
do $$
declare table_name text;
begin
  if not exists(select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  foreach table_name in array array['profiles','listings','reservations','saved_items'] loop
    if not exists(select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = table_name) then
      execute format('alter publication supabase_realtime add table public.%I',table_name);
    end if;
  end loop;
end;
$$;

notify pgrst, 'reload schema';
commit;

-- ===========================================================================
-- 202610120001_feedback_admin_demo.sql
-- ===========================================================================
-- Additive upgrade. Apply after 202609210001; do not rerun the original migration.
begin;

-- Reviewed for the 2026-10-30 Data API default-grant change:
-- this upgrade creates NO public tables/views/sequences. Existing table and
-- column grants from 202609210001 remain valid (including SELECT of new columns).
-- New RPCs opt in explicitly below; no ALL TABLES/default-privilege grants.

alter table public.profiles
  add column role text not null default 'student' check (role in ('student','admin')),
  add column is_demo boolean not null default false;
alter table public.listings
  add column is_demo boolean not null default false,
  add column seed_key text unique,
  add column archived_at timestamptz,
  add column archived_by uuid references public.profiles(id);
create index listings_visible_idx on public.listings(status,created_at desc) where archived_at is null;
comment on column public.profiles.role is 'Managed only by a trusted database administrator, never signup metadata.';
comment on column public.listings.is_demo is 'Synthetic catalog content; cannot participate in real reservations or impact.';

create function public.is_kostcycle_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from public.profiles where id = (select auth.uid()) and role = 'admin' and not is_demo);
$$;
revoke all on function public.is_kostcycle_admin() from public,anon,authenticated;
grant execute on function public.is_kostcycle_admin() to anon,authenticated;

-- Existing profile column grants deliberately do NOT include role/is_demo.
-- Existing student policies are tightened; no real records are deleted or rewritten.
alter policy listings_read on public.listings
  using (archived_at is null or seller_id = (select auth.uid()) or (select public.is_kostcycle_admin()));
alter policy listings_update_self_available on public.listings
  using (seller_id = (select auth.uid()) and status = 'AVAILABLE' and archived_at is null and not is_demo)
  with check (seller_id = (select auth.uid()) and status = 'AVAILABLE' and archived_at is null and not is_demo);
alter policy listings_delete_self_available on public.listings
  using (seller_id = (select auth.uid()) and status = 'AVAILABLE' and archived_at is null and not is_demo);
create policy reservations_admin_read on public.reservations for select to authenticated
  using ((select public.is_kostcycle_admin()));
create policy listings_admin_moderate on public.listings for update to authenticated
  using ((select public.is_kostcycle_admin())) with check ((select public.is_kostcycle_admin()));
grant update(archived_at,archived_by) on public.listings to authenticated;

-- Optional NODE-ONLY seed: declare its minimum Data API privileges explicitly.
-- service_role is a trusted server/local administrator, NEVER a browser role/key.
-- Existing wider service_role grants are preserved; no student gains these grants.
grant usage on schema public to service_role;
grant select(id,role,is_demo), update(is_demo) on public.profiles to service_role;
grant select(seed_key,is_demo,seller_id,archived_at) on public.listings to service_role;
grant insert(seller_id,name,category,condition,price,university,campus,residence,
  distance,pickup,description,image_index,image_data,is_demo,seed_key)
  on public.listings to service_role;
grant execute on function public.kostcycle_category_weight(text) to service_role;

-- RLS policies combine with OR, so a trigger also protects moderation columns
-- and prevents admins from using their policy to edit somebody else's content.
create function kostcycle_private.guard_listing_changes() returns trigger
language plpgsql set search_path = '' as $$
begin
  if current_user in ('anon','authenticated') then
    if (to_jsonb(new) - array['archived_at','archived_by','updated_at','is_free','estimated_weight']) is distinct from
       (to_jsonb(old) - array['archived_at','archived_by','updated_at','is_free','estimated_weight']) then
      if old.seller_id <> auth.uid() or old.status <> 'AVAILABLE' or old.archived_at is not null or old.is_demo then
        raise exception 'Only the seller can edit available, unarchived student listings.';
      end if;
    end if;
    if new.archived_at is distinct from old.archived_at or new.archived_by is distinct from old.archived_by then
      if not public.is_kostcycle_admin() then raise exception 'Admin access required.'; end if;
      if old.status <> 'AVAILABLE' then raise exception 'Only available listings can be archived or restored.'; end if;
      new.archived_by := case when new.archived_at is null then null else auth.uid() end;
      new.archived_at := case when new.archived_at is null then null else now() end;
    end if;
  end if;
  return new;
end;
$$;
create trigger listings_moderation_guard before update on public.listings
  for each row execute function kostcycle_private.guard_listing_changes();

create function public.moderate_listing(p_listing_id uuid, p_archive boolean) returns void
language plpgsql security invoker set search_path = '' as $$
begin
  if not public.is_kostcycle_admin() then raise exception 'Admin access required.'; end if;
  if p_archive is null then raise exception 'Choose archive or restore.'; end if;
  update public.listings set archived_at = case when p_archive then now() else null end,
    archived_by = case when p_archive then auth.uid() else null end
    where id = p_listing_id and status = 'AVAILABLE';
  if not found then raise exception 'Listing is missing or already reserved.'; end if;
end;
$$;
revoke all on function public.moderate_listing(uuid,boolean) from public,anon,authenticated;
grant execute on function public.moderate_listing(uuid,boolean) to authenticated;

-- This protects the ORIGINAL reserve_item RPC too, without rewriting it.
-- Its listing row lock is shared with archive updates, serializing both actions.
create function kostcycle_private.guard_reservation_catalog() returns trigger
language plpgsql security definer set search_path = '' as $$
declare item public.listings%rowtype;
begin
  select * into item from public.listings where id = new.listing_id for update;
  if item.archived_at is not null then raise exception 'This listing has been archived.'; end if;
  if item.is_demo or exists(select 1 from public.profiles where id in (new.buyer_id,new.seller_id) and is_demo) then
    raise exception 'Demo listings are for browsing only. Reserve a student listing to arrange a real pickup.';
  end if;
  return new;
end;
$$;
create trigger reservations_catalog_guard before insert on public.reservations
  for each row execute function kostcycle_private.guard_reservation_catalog();
revoke all on function kostcycle_private.guard_listing_changes(), kostcycle_private.guard_reservation_catalog() from public,anon,authenticated;

-- New columns travel with existing table Realtime events. Pickup secrets stay private.
notify pgrst, 'reload schema';
commit;

-- ===========================================================================
-- 202610260001_binus_student_email.sql
-- ===========================================================================
-- KostCycle: only @binus.ac.id addresses may create or move to an account.
-- Pairs with Supabase "Confirm email" (dashboard setting) so the student must
-- also prove they own the inbox. Existing accounts are not modified.
-- Demo seed accounts (app_metadata.seed_namespace, settable only with the
-- service-role key) are exempt so `npm run seed:demo` keeps working.
begin;

create schema if not exists kostcycle_private;

create or replace function kostcycle_private.require_binus_email() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.email is not distinct from old.email then
    return new;
  end if;
  if coalesce(new.raw_app_meta_data->>'seed_namespace', '') = 'kostcycle-demo-v1' then
    return new;
  end if;
  if new.email is null or lower(btrim(new.email)) !~ '^[^@[:space:]]+@binus\.ac\.id$' then
    raise exception 'binus_email_required: KostCycle accounts need a @binus.ac.id email'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

drop trigger if exists kostcycle_require_binus_email on auth.users;
create trigger kostcycle_require_binus_email before insert or update of email on auth.users
for each row execute function kostcycle_private.require_binus_email();

commit;

-- ===========================================================================
-- 202611210001_reservations_chat_images.sql
-- ===========================================================================
-- KostCycle: reservation cancel + expiry, buyer/seller chat, listing images in
-- Supabase Storage, and saved onboarding interests.
-- Apply once, after 202610260001_binus_student_email.sql. Additive: existing
-- rows are kept. Every new table/function opts in to the Data API explicitly
-- (no default grants are relied on; see the 2026-10-30 Supabase change).
begin;

-- ---------------------------------------------------------------------------
-- 1. Reservations: cancel and expiry
-- ---------------------------------------------------------------------------
alter table public.reservations
  add column cancelled_at timestamptz,
  add column cancelled_by uuid references public.profiles(id) on delete set null,
  add column expires_at timestamptz not null default now() + interval '48 hours';
comment on column public.reservations.expires_at is
  'Unconfirmed pickups are released after this time by expire_overdue_reservations().';

-- The original status checks were auto-named, and listing_id was UNIQUE (one
-- reservation per listing forever). Replace both so a cancelled or expired
-- reservation stays as history while the item can be reserved again.
do $$
declare c record;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'public.reservations'::regclass and contype = 'c'
      and pg_get_constraintdef(oid) like '%status%'
  loop
    execute format('alter table public.reservations drop constraint %I', c.conname);
  end loop;
  for c in
    select conname from pg_constraint
    where conrelid = 'public.reservations'::regclass and contype = 'u'
      and pg_get_constraintdef(oid) = 'UNIQUE (listing_id)'
  loop
    execute format('alter table public.reservations drop constraint %I', c.conname);
  end loop;
end;
$$;
alter table public.reservations
  add constraint reservations_status_check
    check (status in ('RESERVED','COMPLETED','CANCELLED','EXPIRED')),
  add constraint reservations_lifecycle_check check (
    (status = 'RESERVED' and completed_at is null and cancelled_at is null)
    or (status = 'COMPLETED' and completed_at is not null and cancelled_at is null)
    or (status in ('CANCELLED','EXPIRED') and cancelled_at is not null and completed_at is null));
create unique index reservations_one_live_per_listing
  on public.reservations(listing_id) where status in ('RESERVED','COMPLETED');
create index reservations_expiry_idx on public.reservations(expires_at) where status = 'RESERVED';

-- 48 hours, but never before the end of the day after the chosen pickup date
-- (Jakarta time), so a "This weekend" pickup is not released early.
create function kostcycle_private.set_reservation_expiry() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.expires_at := greatest(
    now() + interval '48 hours',
    (new.pickup_date + 2)::timestamp at time zone 'Asia/Jakarta');
  return new;
end;
$$;
create trigger reservations_set_expiry before insert on public.reservations
  for each row execute function kostcycle_private.set_reservation_expiry();

-- Shared release step: end the reservation, delete its pickup code, reopen the listing.
create function kostcycle_private.release_reservation(p_id uuid, p_status text, p_by uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v public.reservations%rowtype;
begin
  if p_status not in ('CANCELLED','EXPIRED') then raise exception 'Invalid release status.'; end if;
  update public.reservations
    set status = p_status, cancelled_at = now(), cancelled_by = p_by
    where id = p_id and status = 'RESERVED'
    returning * into v;
  if not found then return; end if;
  delete from kostcycle_private.pickup_secrets where reservation_id = p_id;
  update public.listings set status = 'AVAILABLE' where id = v.listing_id and status = 'RESERVED';
end;
$$;

-- Buyer or seller may cancel while the pickup is still pending.
create function public.cancel_reservation(p_listing_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_user uuid := auth.uid();
  v public.reservations%rowtype;
begin
  if v_user is null then raise exception 'Sign in to cancel a reservation.'; end if;
  -- Same lock order as reserve_item/confirm_handoff: listing first, then reservation.
  perform 1 from public.listings where id = p_listing_id for update;
  select * into v from public.reservations
    where listing_id = p_listing_id and status = 'RESERVED' for update;
  if not found then raise exception 'There is no active reservation to cancel.'; end if;
  if v_user not in (v.buyer_id, v.seller_id) then
    raise exception 'Only the buyer or seller can cancel this reservation.';
  end if;
  perform kostcycle_private.release_reservation(v.id, 'CANCELLED', v_user);
  return v.id;
end;
$$;

-- Releases every overdue pickup. Safe for anyone to call (it only ever expires
-- reservations whose time is up); the app calls it on its 30 s reconcile, so
-- no pg_cron job is needed. Rows locked by a concurrent handoff are skipped.
create function public.expire_overdue_reservations() returns integer
language plpgsql security definer set search_path = '' as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select id, listing_id from public.reservations
    where status = 'RESERVED' and expires_at <= now()
    order by expires_at limit 200
  loop
    perform 1 from public.listings where id = r.listing_id for update skip locked;
    if not found then continue; end if;
    perform 1 from public.reservations
      where id = r.id and status = 'RESERVED' and expires_at <= now() for update skip locked;
    if not found then continue; end if;
    perform kostcycle_private.release_reservation(r.id, 'EXPIRED', null);
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- reserve_item now clears overdue pickups first, so an expired item can be
-- reserved again straight away. Body otherwise identical to 202609210001.
create or replace function public.reserve_item(p_listing_id uuid, p_pickup_period text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_user uuid := auth.uid();
  v_listing public.listings%rowtype;
  v_id uuid;
  v_code text;
  v_today date := (now() at time zone 'Asia/Jakarta')::date;
  v_pickup_date date;
begin
  if v_user is null then raise exception 'Sign in to reserve an item.'; end if;
  perform public.expire_overdue_reservations();
  if not exists(select 1 from public.profiles where id = v_user) then raise exception 'Your student profile is not ready.'; end if;
  select * into v_listing from public.listings where id = p_listing_id for update;
  if not found or v_listing.status <> 'AVAILABLE' then raise exception 'This item is no longer available to reserve.'; end if;
  if v_listing.seller_id = v_user then raise exception 'You cannot reserve your own listing.'; end if;
  if p_pickup_period is null or not (p_pickup_period = any(v_listing.pickup)) then raise exception 'Choose an available pickup period.'; end if;
  v_pickup_date := case p_pickup_period when 'Today' then v_today when 'Tomorrow' then v_today + 1
    else v_today + case when extract(isodow from v_today)::int >= 6 then 0 else 6 - extract(isodow from v_today)::int end end;
  insert into public.reservations(listing_id,buyer_id,seller_id,pickup_location,pickup_period,pickup_date,estimated_weight)
    values(v_listing.id,v_user,v_listing.seller_id,
      case when v_listing.residence = 'Other' then 'Residence common area' else v_listing.residence || ' lobby' end,
      p_pickup_period,v_pickup_date,v_listing.estimated_weight) returning id into v_id;
  v_code := (1000 + (('x' || substr(replace(gen_random_uuid()::text,'-',''),1,4))::bit(16)::int % 9000))::text;
  insert into kostcycle_private.pickup_secrets(reservation_id,code) values(v_id,v_code);
  update public.listings set status = 'RESERVED' where id = v_listing.id;
  return v_id;
end;
$$;

revoke all on function public.cancel_reservation(uuid), public.expire_overdue_reservations()
  from public, anon, authenticated;
grant execute on function public.cancel_reservation(uuid) to authenticated;
grant execute on function public.expire_overdue_reservations() to anon, authenticated;
revoke all on function public.reserve_item(uuid,text) from public, anon, authenticated;
grant execute on function public.reserve_item(uuid,text) to authenticated;
revoke all on function kostcycle_private.release_reservation(uuid,text,uuid),
  kostcycle_private.set_reservation_expiry() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Buyer and seller chat, one thread per reservation
-- ---------------------------------------------------------------------------
create table public.reservation_messages (
  id uuid primary key default gen_random_uuid(),
  reservation_id uuid not null references public.reservations(id) on delete cascade,
  sender_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index reservation_messages_thread_idx on public.reservation_messages(reservation_id, created_at);
comment on table public.reservation_messages is
  'Visible only to that reservation''s buyer and seller, while RESERVED or up to 7 days after it ends.';

alter table public.reservation_messages enable row level security;
create policy reservation_messages_read on public.reservation_messages for select to authenticated
  using (exists(
    select 1 from public.reservations r
    where r.id = reservation_id
      and (select auth.uid()) in (r.buyer_id, r.seller_id)
      and (r.status = 'RESERVED' or coalesce(r.completed_at, r.cancelled_at) > now() - interval '7 days')));
create policy reservation_messages_insert on public.reservation_messages for insert to authenticated
  with check (
    sender_id = (select auth.uid())
    and exists(
      select 1 from public.reservations r
      where r.id = reservation_id
        and (select auth.uid()) in (r.buyer_id, r.seller_id)
        and (r.status = 'RESERVED' or coalesce(r.completed_at, r.cancelled_at) > now() - interval '7 days')));
-- sender_id and created_at are server-set: clients may only write the thread and the text.
revoke all on public.reservation_messages from public, anon, authenticated;
grant select on public.reservation_messages to authenticated;
grant insert(reservation_id, body) on public.reservation_messages to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Listing photos in Supabase Storage (old base64 image_data keeps working)
-- ---------------------------------------------------------------------------
alter table public.listings add column image_url text check (
  image_url is null or (
    char_length(image_url) <= 600
    and image_url ~ '^(https://[a-z0-9-]+\.supabase\.co|http://(127\.0\.0\.1|localhost):54321)/storage/v1/object/public/listing-images/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,120}$'
    and strpos(image_url, '/listing-images/' || seller_id::text || '/') > 0));
comment on column public.listings.image_url is
  'Public URL in the listing-images bucket, inside the seller''s own folder.';
grant insert(image_url), update(image_url) on public.listings to authenticated;

do $$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'Supabase Storage not found: skipped the listing-images bucket.';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('listing-images', 'listing-images', true, 2097152,
      array['image/webp','image/jpeg','image/png'])
    on conflict (id) do update set public = true,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;
  execute 'drop policy if exists kostcycle_listing_images_read on storage.objects';
  execute 'drop policy if exists kostcycle_listing_images_insert on storage.objects';
  execute 'drop policy if exists kostcycle_listing_images_delete on storage.objects';
  execute $p$create policy kostcycle_listing_images_read on storage.objects
    for select to anon, authenticated using (bucket_id = 'listing-images')$p$;
  execute $p$create policy kostcycle_listing_images_insert on storage.objects
    for insert to authenticated
    with check (bucket_id = 'listing-images'
      and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
  execute $p$create policy kostcycle_listing_images_delete on storage.objects
    for delete to authenticated
    using (bucket_id = 'listing-images'
      and (storage.foldername(name))[1] = (select auth.uid())::text)$p$;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Onboarding interests, private to their owner
-- ---------------------------------------------------------------------------
-- Kept out of public.profiles on purpose: profiles are readable by everyone.
create table public.profile_preferences (
  user_id uuid primary key default auth.uid() references public.profiles(id) on delete cascade,
  interests jsonb not null check (jsonb_typeof(interests) = 'object' and pg_column_size(interests) <= 4000),
  updated_at timestamptz not null default now()
);
alter table public.profile_preferences enable row level security;
create policy profile_preferences_read_self on public.profile_preferences for select to authenticated
  using (user_id = (select auth.uid()));
create policy profile_preferences_insert_self on public.profile_preferences for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy profile_preferences_update_self on public.profile_preferences for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create trigger profile_preferences_updated before update on public.profile_preferences
  for each row execute function kostcycle_private.touch_updated_at();
revoke all on public.profile_preferences from public, anon, authenticated;
grant select on public.profile_preferences to authenticated;
grant insert(user_id, interests), update(interests) on public.profile_preferences to authenticated;

-- ---------------------------------------------------------------------------
-- Realtime: chat messages stream to participants (RLS still applies).
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists(select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  if not exists(select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'reservation_messages') then
    alter publication supabase_realtime add table public.reservation_messages;
  end if;
end;
$$;

notify pgrst, 'reload schema';
commit;

